SELECT jsonb_build_object('model','ConsentDisposition','ids',coalesce(jsonb_agg(observed.id::text ORDER BY observed.id::text COLLATE "C"),'[]'::jsonb)) FROM (SELECT id,proof_id,user_id,presentation_id,kind,semantic_key,fingerprint,created_at,mutation_transaction_id FROM app.consent_disposition WHERE id IN ('0d227778-2dcc-5dbb-b7d6-a10509ed527f'::uuid,'f9f011da-46bf-5e7e-98a7-da1c034295a8'::uuid)) observed;
